import{_ as a,o as t,c as e,aj as o}from"./chunks/framework.DuzMo9U1.js";const u=JSON.parse('{"title":"个人项目与工具","description":"网页小工具、Python 界面工具等个人实体项目","frontmatter":{"title":"个人项目与工具","description":"网页小工具、Python 界面工具等个人实体项目"},"headers":[],"relativePath":"pages/skill-tools.md","filePath":"pages/skill-tools.md"}'),i={name:"pages/skill-tools.md"};function r(s,l,n,h,p,c){return t(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="个人项目与工具" tabindex="-1">个人项目与工具 <a class="header-anchor" href="#个人项目与工具" aria-label="Permalink to &quot;个人项目与工具&quot;">​</a></h1><p>这里收录我开发的一些实体项目，包括网页小工具、Python 界面工具等，方便自己使用，也分享给大家。</p><hr><h2 id="网页小工具" tabindex="-1">网页小工具 <a class="header-anchor" href="#网页小工具" aria-label="Permalink to &quot;网页小工具&quot;">​</a></h2><h3 id="svg-转换工具" tabindex="-1">SVG 转换工具 <a class="header-anchor" href="#svg-转换工具" aria-label="Permalink to &quot;SVG 转换工具&quot;">​</a></h3><p><strong>PNG 转 SVG 在线转换工具</strong>（精准比例输出）</p><ul><li>支持 PNG 上传，等比例适配或强制尺寸输出</li><li>可设置输出 SVG 文件大小限制（50KB~无限制）</li><li>适配 LVGL 等嵌入式 UI 场景，转换后可配合 image converter-lvgl 转 C 数组</li><li>所有操作均在本地完成，不上传图片</li></ul><p><strong><a href="/pages/skill-tools-svg.html">打开 SVG 转换工具</a></strong> ← 点击直达工具页面</p><h3 id="mcu-msp-psp-上下文切换演示" tabindex="-1">MCU MSP/PSP 上下文切换演示 <a class="header-anchor" href="#mcu-msp-psp-上下文切换演示" aria-label="Permalink to &quot;MCU MSP/PSP 上下文切换演示&quot;">​</a></h3><p><strong>可视化 MCU 上电、MSP/PSP 栈切换与中断返回流程</strong></p><ul><li>覆盖复位、裸机运行、RTOS 启动、中断触发、任务切换、恢复执行全流程</li><li>通过寄存器面板与双栈视图直观查看上下文变化</li><li>适合讲解 Cortex-M 栈模型与 RTOS 切换机制</li></ul><p><strong><a href="/pages/skill-tools-mcu-core.html">打开 MCU 上下文切换演示</a></strong></p><h3 id="步进电机曲线计算器-图表版" tabindex="-1">步进电机曲线计算器（图表版） <a class="header-anchor" href="#步进电机曲线计算器-图表版" aria-label="Permalink to &quot;步进电机曲线计算器（图表版）&quot;">​</a></h3><p><strong>多种加减速曲线 + 实时图表展示</strong></p><ul><li>支持 S 曲线、梯形、线性、二次、三次、正弦、指数等曲线</li><li>同时展示速度曲线与定时器周期，便于参数调优</li><li>快速验证不同曲线下的动态效果</li></ul><p><strong><a href="/pages/skill-tools-step-motor-view.html">打开步进电机图表版工具</a></strong></p><h3 id="步进电机加减速计算器-高级版" tabindex="-1">步进电机加减速计算器（高级版） <a class="header-anchor" href="#步进电机加减速计算器-高级版" aria-label="Permalink to &quot;步进电机加减速计算器（高级版）&quot;">​</a></h3><p><strong>可自定义加速/减速公式，支持导出加速段参数表</strong></p><ul><li>支持预设曲线与公式自定义测试</li><li>输出加速段台阶参数、频率与定时器周期</li><li>支持 CSV 导出，便于下位机参数落地</li></ul><p><strong><a href="/pages/skill-tools-step-motor.html">打开步进电机高级版工具</a></strong></p><hr><h2 id="后续扩展" tabindex="-1">后续扩展 <a class="header-anchor" href="#后续扩展" aria-label="Permalink to &quot;后续扩展&quot;">​</a></h2><p>后续会陆续添加更多工具，例如：</p><ul><li>Python 编写的 GUI 工具</li><li>其他网页小工具</li><li>开源实体项目链接</li></ul><p>需要添加新工具时，在本页相应分类下增加条目即可。</p>',25)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
